<?php
namespace App\Livewire\Admin\TravelSchedule;
use App\Enums\LeadStatus;use App\Models\CallCenterCall;use App\Models\Lead;use Livewire\Attributes\Url;use Livewire\Component;use Livewire\WithPagination;
class Index extends Component{use WithPagination;public string $mode='departures';#[Url]public string $search='';public function mount(string $mode='departures'):void{$this->mode=$mode;abort_unless(auth()->user()->isAdmin()||auth()->user()->isCallCenter(),403);}public function assignToMe(int $leadId){abort_unless(auth()->user()->isCallCenter(),403);$type=$this->mode==='arrivals'?CallCenterCall::CALL_TYPE_POST_ARRIVAL:CallCenterCall::CALL_TYPE_PRE_DEPARTURE;$call=CallCenterCall::firstOrCreate(['lead_id'=>$leadId,'call_type'=>$type],['assigned_call_center_user'=>auth()->id(),'status'=>CallCenterCall::STATUS_ASSIGNED,'call_attempts'=>0]);if(!$call->assigned_call_center_user)$call->update(['assigned_call_center_user'=>auth()->id(),'status'=>CallCenterCall::STATUS_ASSIGNED]);return $this->redirectRoute('admin.calls.show',$call,navigate:true);}public function render(){$field=$this->mode==='arrivals'?'arrival_date':'depature_date';$type=$this->mode==='arrivals'?CallCenterCall::CALL_TYPE_POST_ARRIVAL:CallCenterCall::CALL_TYPE_PRE_DEPARTURE;$q=Lead::query()->notArchived()->excludingOtherLeads()->where('status',LeadStatus::CONFIRMED->value)->whereNotNull($field)->whereDoesntHave('callCenterCalls',fn($q)=>$q->where('call_type',$type))->when($this->mode==='departures',fn($q)=>$q->whereBetween($field,[today(),today()->addDays(30)]),fn($q)=>$q->whereBetween($field,[today()->subDays(30),today()]))->when($this->search,fn($q)=>$q->where(fn($q)=>$q->where('customer_name','like','%'.$this->search.'%')->orWhere('destination','like','%'.$this->search.'%')));return view('livewire.admin.travel-schedule.index',['leads'=>$q->orderBy($field)->paginate(25),'dateField'=>$field])->layout('components.layouts.admin',['title'=>$this->mode==='arrivals'?'Recent arrivals':'Upcoming departures']);}}
